/* source: curated */
/* algorithm: ime_vmadot_4x4x8 */
/* accuracy_class: bit_exact */
/* origin: generated by pipeline/generate_kernels.py via Codex (gpt-5.6-sol).
 *   Same MAC engine, tiling and pack-once structure as
 *   kernels/ime/ime_matmul_s8_ime_vmadot_4x4x8.c -- read that header for the
 *   four measured facts about smt.vmadot (4x4x8 micro-tile, accumulates,
 *   row-major across the (vd,vd+1) pair, cluster 0 only).
 *
 * TWO THINGS DIFFER FROM THE MATMUL, both in IME's favour:
 *
 *   LAYOUT IS FREE. `weight` is [N,K], indexed weight[n*K + k], so its row
 *   index is the OUTPUT column -- exactly vmadot's vs2 convention. A 4x8
 *   weight tile is 32 contiguous bytes and needs no transpose at all, unlike
 *   matmul_s8's transpose_b=0 case.
 *
 *   THE TAIL IS INTEGER. linear_s8 requantizes with a Q0.31 multiply and a
 *   rounding shift, not a float scale, so a scalar tail is bit-exact by
 *   construction rather than by carefully avoiding a rounding-mode mismatch.
 *
 * OFFSETS. input_offset and filter_offset are added to each operand before
 * the product, and vmadot multiplies raw int8, so a nonzero offset needs
 * sum(a*w) + ia*sum(w) + iw*sum(a) + K*ia*iw. Measured across this tree, all
 * 20 linear_s8 dispatches in every model have both offsets zero -- the
 * quantization is symmetric -- so the fast path is the common one.
 */


void kernel_linear_s8(const int8_t *input, const int8_t *weight, const int32_t *bias, int8_t *output, int M, int K, int N, int input_offset, int filter_offset, int output_offset, int output_multiplier, int output_shift, int activation_min, int activation_max) {
    if (M <= 0 || N <= 0) {
        return;
    }

    int m_tiles = (M + 3) / 4;
    int k_slabs = K > 0 ? (K + 7) / 8 : 1;
    size_t bytes_per_m_tile = (size_t)k_slabs * 32u;
    int8_t packed_input[(size_t)m_tiles * bytes_per_m_tile];
    int8_t packed_weight[(size_t)k_slabs * 32u];
    int32_t input_sums[(size_t)m_tiles * 4u];
    int32_t tile_output[16];

    for (int mt = 0; mt < m_tiles; mt++) {
        int m0 = mt * 4;

        for (int i = 0; i < 4; i++) {
            input_sums[mt * 4 + i] = 0;
        }

        for (int ks = 0; ks < k_slabs; ks++) {
            int k0 = ks * 8;
            int8_t *dst =
                packed_input +
                ((size_t)mt * (size_t)k_slabs + (size_t)ks) * 32u;

            for (int i = 0; i < 4; i++) {
                int row = m0 + i;

                for (int q = 0; q < 8; q++) {
                    int k = k0 + q;
                    int8_t value = 0;

                    if (row < M && k < K) {
                        value = input[(size_t)row * (size_t)K +
                                      (size_t)k];
                        input_sums[mt * 4 + i] += (int32_t)value;
                    }
                    dst[i * 8 + q] = value;
                }
            }
        }
    }

    for (int n0 = 0; n0 < N; n0 += 4) {
        int32_t weight_sums[4] = {0, 0, 0, 0};

        for (int ks = 0; ks < k_slabs; ks++) {
            int k0 = ks * 8;
            int8_t *dst = packed_weight + (size_t)ks * 32u;

            for (int j = 0; j < 4; j++) {
                int col = n0 + j;

                for (int q = 0; q < 8; q++) {
                    int k = k0 + q;
                    int8_t value = 0;

                    if (col < N && k < K) {
                        value = weight[(size_t)col * (size_t)K +
                                       (size_t)k];
                        weight_sums[j] += (int32_t)value;
                    }
                    dst[j * 8 + q] = value;
                }
            }
        }

        for (int mt = 0; mt < m_tiles; mt++) {
            int m0 = mt * 4;
            const int8_t *input_tile =
                packed_input + (size_t)mt * bytes_per_m_tile;
            const int8_t *weight_tile = packed_weight;
            int slabs = k_slabs;
            size_t n32 = 32u;
            size_t n8 = 8u;

            __asm__ volatile(
                "vsetvli t0, %[n32], e8, m1, ta, ma\n\t"
                "vmv.v.i v8, 0\n\t"
                "vmv.v.i v9, 0\n\t"
                "1:\n\t"
                "vsetvli t0, %[n32], e8, m1, ta, ma\n\t"
                "vle8.v v0, (%[pa])\n\t"
                "vle8.v v4, (%[pb])\n\t"
                "vsetvli t0, %[n32], e8, m1, ta, ma\n\t"
                ".insn r 0x2b, 3, 0x71, x8, x0, x4\n\t"
                "addi %[pa], %[pa], 32\n\t"
                "addi %[pb], %[pb], 32\n\t"
                "addi %[ks], %[ks], -1\n\t"
                "bnez %[ks], 1b\n\t"
                "vsetvli t0, %[n8], e32, m1, ta, ma\n\t"
                "vse32.v v8, (%[o0])\n\t"
                "vse32.v v9, (%[o1])\n\t"
                : [pa] "+r"(input_tile),
                  [pb] "+r"(weight_tile),
                  [ks] "+r"(slabs)
                : [o0] "r"(tile_output),
                  [o1] "r"(tile_output + 8),
                  [n32] "r"(n32),
                  [n8] "r"(n8)
                : "t0", "memory", "v0", "v4", "v8", "v9");

            for (int i = 0; i < 4 && m0 + i < M; i++) {
                for (int j = 0; j < 4 && n0 + j < N; j++) {
                    int32_t acc = tile_output[i * 4 + j];

                    if (bias != NULL) {
                        acc += bias[n0 + j];
                    }

                    if (input_offset != 0 || filter_offset != 0) {
                        int64_t correction =
                            (int64_t)input_offset *
                                (int64_t)weight_sums[j] +
                            (int64_t)filter_offset *
                                (int64_t)input_sums[mt * 4 + i] +
                            (int64_t)K *
                                (int64_t)input_offset *
                                (int64_t)filter_offset;
                        acc = (int32_t)((int64_t)acc + correction);
                    }

                    int64_t prod =
                        (int64_t)acc * (int64_t)output_multiplier;
                    prod = (prod + (1LL << 30)) >> 31;

                    int32_t scaled = (int32_t)prod;
                    if (output_shift > 0) {
                        scaled = (int32_t)(
                            ((int64_t)scaled +
                             ((int64_t)1 << (output_shift - 1))) >>
                            output_shift);
                    } else if (output_shift < 0) {
                        scaled = scaled << (-output_shift);
                    }

                    scaled += output_offset;
                    if (scaled < activation_min) {
                        scaled = activation_min;
                    }
                    if (scaled > activation_max) {
                        scaled = activation_max;
                    }

                    output[(size_t)(m0 + i) * (size_t)N +
                           (size_t)(n0 + j)] = (int8_t)scaled;
                }
            }
        }
    }
}
